}

/* 의견 및 질문 페이징 버튼(좌,우) 페이징 처리
 * no : 이동할 위치 ( 1: 다음 / -1 : 이전)
 */
function fn_pageMove(no){
	var pIdx = parseInt($("input[name=pageIndex]").val()) + (no);
	if(pIdx < 1 || parseInt($("#tPage").val()) < pIdx){return false;}
	fn_paging(pIdx);
}

