		$("input[name=bbs_title]").val("");
		$("textarea[name=bbs_content]").val("");

		//파일 초기화
		for (var i = 0; i < "2"; i++) {
			$("#upfile_"+i).val("");
		}

		if(type == "update"){//수정
			$("input[name=levl]").val("0");
			$("input[name=up_bbs_no]").val("0");
			$("input[name=bbs_no]").val(bbsNo);
