/* 관심지표 > 분류그룹 추가 저장*/
function fn_saveGroup(){
	let grpNm = $("#grpNm").val();
	if(JStrLen(JTrim(grpNm)) == 0 ){
		alert("그룹명을 입력하여 주십시오");
		$("#grpNm").focus();
	}else if(JStrLen(JTrim(grpNm)) > 20){
		alert("그룹명 입력 길이를 초과 하였습니다. \n한글 10자, 영문 20자를 초과 할 수 없습니다.");
		$("#grpNm").focus();
		return false;
	}else{
		let changeStatus = false;

		/*나의 관심지표 그룹 array 생성*/
		let idxGrpNmArr = new Array();
		
		idxGrpNmArr.forEach(element => {
			if(element == grpNm){  //이미 있는 분류 이름 구분
				changeStatus = true;
			}
		});

		if(changeStatus){
			alert("이미 등록된 분류그룹입니다");
			$("#grpNm").focus();
			return false;
		}else{
				$.ajax({
					type:"POST",
					url : "/unity/potal/eNara/ajax/insertMyIdxGroup.do",
					data: {"userId" : ""
						 , "grpNm" : $("#grpNm").val()},
					dataType:"json",
					async:false,
					success:function(data){
						if(data.result > 0){
							alert("분류 그룹이 추가 되었습니다.");
